pub fn verify_secp224r1_ecdsa<let HASH_BYTE_SIZE: u32>(
    public_key_x: Secp224r1_Fq,
    public_key_y: Secp224r1_Fq,
    message_digest: [u8; HASH_BYTE_SIZE],
